const evictRoot = (path, reason) => {
  const done = evictTrees(path, { apply });
  for (const t of done.evicted) evicted.push({ path: t.path, reason, ignored: t.ignored });
  failed.push(...done.failed);
  skipped.push(...done.skipped);
};

const ofThisRun = (applied, at) => (applied !== null && at != null && applied.run === at ? applied : null);
export const reapedAfter = (applied, at) => ofThisRun(applied, at)?.reapAfter ?? [];
export const sweptAfter = (applied, at) => ofThisRun(applied, at)?.sweptAfter ?? [];
export const reapDue = (done, applied, at) => { const ran = new Set(reapedAfter(applied, at)); return done.filter((n) => !ran.has(n)); };
